function RcaIncidentShelf({
  incidents,
  isLoading,
  onRefresh,
  onSelectIncident,
  selectedIncidentId
}: {
  incidents: RcaIncident[];
  isLoading: boolean;
  onRefresh: () => void;
  onSelectIncident: (incidentId: string) => void;
  selectedIncidentId: string | null;
}) {
  const activeCount = incidents.filter((incident) => incident.status !== 'CLOSED').length;
  const investigatingCount = incidents.filter((incident) => incident.status === 'INVESTIGATING').length;
  const highRiskCount = incidents.filter((incident) => incident.rpnScore >= 25 && incident.status !== 'CLOSED').length;

  return (
    <aside className="rca-incident-shelf pointer-events-auto mt-2 flex min-h-0 flex-1 flex-col overflow-hidden rounded-[22px] border border-white/60 bg-white/82 shadow-xl shadow-slate-900/10 ring-1 ring-slate-900/5 backdrop-blur-xl">
      <div className="shrink-0 flex items-center justify-between border-b border-slate-200/70 px-4 py-3">
        <div>
          <h2 className="text-sm font-semibold text-slate-950">Incident queue</h2>
          <p className="text-xs text-slate-500">
            {isLoading ? 'Refreshing live queue...' : `${activeCount} active / ${investigatingCount} investigating / ${highRiskCount} elevated risk`}
          </p>
        </div>
        <button
          className="inline-flex min-h-[36px] items-center justify-center gap-1.5 rounded-xl border border-slate-200 bg-white px-3 text-xs font-semibold text-slate-700 transition hover:border-cyan-300 hover:text-cyan-700"
          onClick={onRefresh}
          type="button"
        >
          <RefreshCw aria-hidden="true" size={13} />
          Refresh
        </button>
      </div>
      <div className="rca-hidden-scrollbar min-h-0 flex-1 space-y-2 overflow-y-auto p-3">
        {incidents.length ? incidents.map((incident) => {
          const assetSummary = getRcaIncidentAssetSummary(incident);
          const displayId = incident.displayId || buildFriendlyRcaDisplayId('RCA', incident.id, incident.createdAtIso);
          const riskBand = getRcaRiskBand(incident.rpnScore);
          const stageLabel = getRcaIncidentStageLabel(incident);
          const isDefaultRiskProfile = isDefaultRcaRiskProfile(incident.riskFactors);

          return (
            <button
              className={`w-full rounded-2xl border px-3 py-2.5 text-left transition active:scale-[0.99] ${
                selectedIncidentId === incident.id
                  ? 'border-cyan-300 bg-cyan-50 ring-4 ring-cyan-500/10'
                  : 'border-slate-200 bg-white/80 hover:bg-white'
              }`}
              key={incident.id}
              onClick={() => onSelectIncident(incident.id)}
              type="button"
            >
              <div className="flex items-start justify-between gap-3">
                <div className="min-w-0">
                  <p className="text-[10px] font-semibold uppercase tracking-[0.16em] text-cyan-700">{displayId}</p>
                  <p className="mt-0.5 line-clamp-2 text-sm font-semibold leading-5 text-slate-950">{incident.title || 'Untitled RCA project'}</p>
                </div>
                <span className={`shrink-0 rounded-full px-2.5 py-1 text-xs font-normal ring-1 ${riskBand.className}`}>
                  {isDefaultRiskProfile ? 'Risk pending' : `Risk ${incident.rpnScore}`}
                </span>
              </div>
              <div className="mt-1.5 grid grid-cols-[1fr_auto] items-center gap-2 text-xs">
                <span className={`min-w-0 break-words ${assetSummary.isAssigned ? 'text-slate-500' : 'text-amber-700'}`}>{assetSummary.label}</span>
                <span className="rounded-full bg-white/80 px-2 py-1 font-normal text-slate-600 ring-1 ring-slate-200">{stageLabel}</span>
              </div>
              <div className="mt-1.5 flex flex-wrap items-center gap-1.5 text-[11px] font-normal text-slate-500">
                {isDefaultRiskProfile ? (
                  <span className="rounded-full bg-slate-100 px-2 py-1">Initial risk values pending triage</span>
                ) : (
                  <>
                    <span className="rounded-full bg-slate-100 px-2 py-1">Severity {incident.riskFactors.severity}</span>
                    <span className="rounded-full bg-slate-100 px-2 py-1">Occurrence {incident.riskFactors.occurrence}</span>
                    <span className="rounded-full bg-slate-100 px-2 py-1">Detection {incident.riskFactors.detection}</span>
                  </>
                )}
                <span className="rounded-full bg-slate-100 px-2 py-1">{formatStatus(incident.status)}</span>
              </div>
            </button>
          );
        }) : (
          <div className="rounded-2xl border border-dashed border-slate-300 bg-white/70 p-5 text-sm text-slate-500">
            No RCA incidents are open yet.
          </div>
        )}
      </div>
    </aside>
  );
}

function RcaIncidentLauncher({
  draft,
  isOpen,
  isWorking,
  onClose,
  onCreateIncident,
  onDraftChange
}: {
  draft: {
    title: string;
  };
  isOpen: boolean;
  isWorking: boolean;
  onClose: () => void;
  onCreateIncident: (event: React.FormEvent<HTMLFormElement>) => void;
  onDraftChange: React.Dispatch<React.SetStateAction<{
    title: string;
  }>>;
}) {
  const [modalOffset, setModalOffset] = React.useState({ x: 0, y: 0 });
  const dragStateRef = React.useRef<{
    originX: number;
    originY: number;
    pointerId: number;
    startX: number;
    startY: number;
  } | null>(null);

  React.useEffect(() => {
    if (isOpen) {
      setModalOffset({ x: 0, y: 0 });
    }
  }, [isOpen]);

  if (!isOpen) {
    return null;
  }

  const handleDragStart = (event: React.PointerEvent<HTMLDivElement>) => {
    if (event.button !== 0 || (event.target as HTMLElement).closest('button')) {
      return;
    }

    dragStateRef.current = {
      originX: modalOffset.x,
      originY: modalOffset.y,
      pointerId: event.pointerId,
      startX: event.clientX,
      startY: event.clientY
    };

    event.currentTarget.setPointerCapture(event.pointerId);
  };
  const handleDragMove = (event: React.PointerEvent<HTMLDivElement>) => {
    const dragState = dragStateRef.current;

    if (!dragState || dragState.pointerId !== event.pointerId) {
      return;
    }

    setModalOffset({
      x: dragState.originX + event.clientX - dragState.startX,
      y: dragState.originY + event.clientY - dragState.startY
    });
  };
  const handleDragEnd = (event: React.PointerEvent<HTMLDivElement>) => {
    const dragState = dragStateRef.current;

    if (!dragState || dragState.pointerId !== event.pointerId) {
      return;
    }

    dragStateRef.current = null;

    if (event.currentTarget.hasPointerCapture(event.pointerId)) {
      event.currentTarget.releasePointerCapture(event.pointerId);
    }
  };

  return (
    <>
      <button
        aria-label="Close incident launcher"
        className="fixed inset-0 z-50 cursor-default bg-transparent"
        onClick={onClose}
        type="button"
      />
      <form
        className="fixed left-1/2 top-1/2 z-[60] w-[min(560px,calc(100%-32px))] rounded-[28px] border border-white/70 bg-white/95 p-5 shadow-2xl shadow-slate-950/20 ring-1 ring-slate-900/5 backdrop-blur-xl will-change-transform"
        onSubmit={onCreateIncident}
        style={{ transform: `translate(-50%, -50%) translate3d(${modalOffset.x}px, ${modalOffset.y}px, 0)` }}
      >
        <div
          className="mb-5 flex touch-none select-none items-start justify-between gap-4 cursor-grab active:cursor-grabbing"
          onPointerCancel={handleDragEnd}
          onPointerDown={handleDragStart}
          onPointerMove={handleDragMove}
          onPointerUp={handleDragEnd}
        >
          <div>
            <p className="text-xs font-semibold uppercase tracking-[0.22em] text-cyan-700">Initialize war room</p>
            <h2 className="mt-1 text-2xl font-semibold tracking-tight text-slate-950">Create RCA project</h2>
            <p className="mt-1 text-sm text-slate-500">Create the project shell. Incident details are captured on the canvas.</p>
          </div>
          <button
            className="inline-flex min-h-[40px] min-w-[40px] items-center justify-center rounded-2xl border border-slate-200 bg-white text-slate-600 transition hover:bg-slate-50 active:scale-95"
            onClick={onClose}
            type="button"
          >
            <X aria-hidden="true" size={17} />
          </button>
        </div>
        <div className="grid gap-3">
          <input
            className="h-12 w-full rounded-2xl border border-slate-200 bg-white px-4 text-sm text-slate-900 outline-none ring-cyan-500/20 transition placeholder:text-slate-400 focus:border-cyan-400 focus:ring-4"
            maxLength={RCA_INCIDENT_TITLE_MAX_LENGTH}
            onChange={(event) => onDraftChange((currentDraft) => ({
              ...currentDraft,
              title: event.target.value.slice(0, RCA_INCIDENT_TITLE_MAX_LENGTH)
            }))}
            placeholder="Project title"
            required
            type="text"
            value={draft.title}
          />
          <button
            className="mt-2 inline-flex min-h-[48px] w-full items-center justify-center gap-2 rounded-2xl bg-cyan-600 px-5 text-sm font-semibold text-white shadow-lg shadow-cyan-900/16 transition hover:bg-cyan-700 active:scale-[0.99] disabled:cursor-not-allowed disabled:opacity-60"
            disabled={isWorking || !draft.title.trim()}
            type="submit"
          >
            <ShieldCheck aria-hidden="true" size={18} />
            Open war room
          </button>
        </div>
      </form>
    </>
  );
}

function RcaCanvasToolbar({
  activityLogCount,
  canWalkBranches,
  canGenerateReport,
  isAutoFocusSelectionEnabled,
  isActivityLogOpen,
  isBranchWalkthroughOpen,
  isConnectionRecommendationsOpen,
  isGuidedPathOpen,
  isReferenceProject,
  isWorking,
  methodology,
  onAutoArrange,
  onCreateSession,
  onEnterPresentationMode,
  onGenerateReport,
  onOpenBranchWalkthrough,
  onToggleConnectionRecommendations,
  onToggleActivityLog,
  onToggleAutoFocusSelection,
  onToggleGuidedPath,
  onMethodologyChange,
  onOpenIncidentLauncher,
  recommendationCount,
  connectionRecommendationCount,
  session
}: {
  activityLogCount: number;
  canWalkBranches: boolean;
  canGenerateReport: boolean;
  isAutoFocusSelectionEnabled: boolean;
  isActivityLogOpen: boolean;
  isBranchWalkthroughOpen: boolean;
  isConnectionRecommendationsOpen: boolean;
  isGuidedPathOpen: boolean;
  isReferenceProject: boolean;
  isWorking: boolean;
  methodology: RcaMethodology;
  onAutoArrange: () => void;
  onCreateSession: () => void;
  onEnterPresentationMode: () => void;
  onGenerateReport: () => void;
  onOpenBranchWalkthrough: () => void;
  onToggleConnectionRecommendations: () => void;
  onToggleActivityLog: () => void;
  onToggleAutoFocusSelection: () => void;
  onToggleGuidedPath: () => void;
  onMethodologyChange: (methodology: RcaMethodology) => void;
  onOpenIncidentLauncher: () => void;
  recommendationCount: number;
  connectionRecommendationCount: number;
  session: RcaSession | null;
}) {
  const [isToolbarMinimized, setIsToolbarMinimized] = React.useState(false);

  if (isToolbarMinimized) {
    return (
      <button
        aria-label="Show RCA toolbar"
        className="absolute bottom-6 left-1/2 z-50 grid h-9 w-9 -translate-x-1/2 place-items-center rounded-full border border-slate-200/80 bg-white/95 text-slate-700 shadow-[0_16px_40px_rgba(15,23,42,0.18),0_3px_10px_rgba(14,165,233,0.12)] ring-1 ring-white/80 backdrop-blur-xl transition hover:-translate-y-0.5 hover:border-cyan-200 hover:text-cyan-700 active:scale-95 max-lg:bottom-4"
        onClick={() => setIsToolbarMinimized(false)}
        title="Show RCA toolbar"
        type="button"
      >
        <PanelBottomOpen aria-hidden="true" size={15} strokeWidth={1.8} />
      </button>
    );
  }

  /**
   * One button, three states.
   *
   * The bar had grown four different button treatments — borderless, outlined,
   * solid cyan and a tinted variant — so nothing on it read as belonging to
   * anything else, and "selected" meant two different things depending on which
   * button you were looking at. A control bar is a row of peers; they should
   * differ by what they say, not by how they are drawn.
   */
  const toolbarButtonClass =
    'inline-flex min-h-[32px] shrink-0 items-center justify-center gap-1.5 rounded-[10px] px-3 text-[12.5px] font-medium leading-none text-slate-600 transition-colors duration-150 hover:bg-slate-900/[0.06] hover:text-slate-900 active:scale-[0.98] disabled:cursor-not-allowed disabled:opacity-40 disabled:hover:bg-transparent';
  const toolbarPanelButtonClass = toolbarButtonClass;
  /**
   * The selected state is a filled pill, and it is the only filled thing on the
   * bar. A tint plus a ring reads as a hover on a light background, which is
   * why the previously selected panel buttons were easy to miss.
   */
  const toolbarActiveButtonClass =
    'bg-cyan-600 text-white shadow-[0_6px_16px_rgba(8,145,178,0.30)] hover:bg-cyan-600 hover:text-white';
  const toolbarIconButtonClass =
    'grid h-[32px] w-[32px] shrink-0 place-items-center rounded-[10px] text-slate-500 transition-colors duration-150 hover:bg-slate-900/[0.06] hover:text-slate-900 active:scale-[0.98] disabled:cursor-not-allowed disabled:opacity-40 disabled:hover:bg-transparent';
  const toolbarDividerClass = 'h-5 w-px shrink-0 bg-slate-900/10';

  /**
   * The bar scrolls when it must, rather than losing its own controls.
   *
   * The report, activity log and minimise buttons sit at the end, and on a
   * narrower window they were pushed out with no way to reach them — which is
   * why they looked missing. It now stays inside the viewport and scrolls
   * sideways instead of hiding what it cannot fit.
   */
  return (
    <div className="absolute bottom-6 left-1/2 z-50 flex max-w-[calc(100vw-32px)] -translate-x-1/2 items-center gap-0.5 overflow-x-auto rounded-[16px] border border-slate-900/[0.06] bg-white/90 p-1.5 shadow-[0_18px_50px_rgba(15,23,42,0.16)] ring-1 ring-white/60 backdrop-blur-2xl max-lg:bottom-4 max-lg:w-[calc(100%-24px)]">
      <button
        className={toolbarButtonClass}
        onClick={onOpenIncidentLauncher}
        type="button"
      >
        Incident
      </button>
      <span className={toolbarDividerClass} />
      {methodologyOptions.map((option) => {
        const isSelected = option.value === methodology;

        return (
          <button
            aria-pressed={isSelected}
            className={`${toolbarButtonClass} ${isSelected ? toolbarActiveButtonClass : ''}`}
            disabled={!session || isWorking}
            key={option.value}
            onClick={() => onMethodologyChange(option.value)}
            title={`${option.shortcut} - ${option.label}`}
            type="button"
          >
            {option.label}
          </button>
        );
      })}
      <span className={toolbarDividerClass} />
      <button
        className={toolbarButtonClass}
        disabled={!session || isWorking}
        onClick={onAutoArrange}
        title="R - Rearrange canvas"
        type="button"
      >
        Rearrange Canvas
      </button>
      {isReferenceProject ? (
        <>
          <span className={toolbarDividerClass} />
          <span className="inline-flex min-h-[34px] shrink-0 items-center gap-1.5 rounded-[13px] border border-emerald-200/80 bg-emerald-50/90 px-2.5 text-[12px] font-semibold leading-none text-emerald-700">
            <BadgeCheck aria-hidden="true" size={13} strokeWidth={1.85} />
            Sealed
          </span>
        </>
      ) : !session ? (
        <>
          <span className={toolbarDividerClass} />
          <button
            className="inline-flex min-h-[34px] shrink-0 items-center justify-center gap-1.5 rounded-[13px] bg-cyan-600 px-3 text-[12px] font-semibold leading-none text-white shadow-[0_10px_22px_rgba(8,145,178,0.24)] transition hover:bg-cyan-500 active:scale-95 disabled:cursor-not-allowed disabled:opacity-60"
            disabled={isWorking}
            onClick={onCreateSession}
            type="button"
          >
            <ShieldCheck aria-hidden="true" size={13} strokeWidth={1.85} />
            Start Session
          </button>
        </>
      ) : null}
      <span className={toolbarDividerClass} />
      <button
        className={toolbarPanelButtonClass}
        disabled={!session}
        onClick={onEnterPresentationMode}
        title="Start Presentation Mode"
        type="button"
      >
        Present
      </button>
      <button
        className={`${toolbarPanelButtonClass} ${
          isBranchWalkthroughOpen
            ? toolbarActiveButtonClass
            : ''
        }`}
        disabled={!session || !canWalkBranches}
        onClick={onOpenBranchWalkthrough}
        title={canWalkBranches ? 'Walk through Ishikawa branches' : 'Add the Fishbone branch structure first'}
        type="button"
      >
        Branches
      </button>
      <button
        className={`${toolbarPanelButtonClass} ${
          isGuidedPathOpen
            ? toolbarActiveButtonClass
            : ''
        }`}
        disabled={!session}
        onClick={onToggleGuidedPath}
        title="Validate selected node"
        type="button"
      >
        Validate
        {recommendationCount > 0 ? (
          <span className="ml-0.5 rounded-full bg-cyan-100 px-1.5 py-0.5 text-[10px] font-bold text-cyan-800 shadow-sm ring-1 ring-cyan-200/70">
            {recommendationCount}
          </span>
        ) : null}
      </button>
      <button
        className={`${toolbarPanelButtonClass} ${
          isConnectionRecommendationsOpen
            ? toolbarActiveButtonClass
            : ''
        }`}
        disabled={!session}
        onClick={onToggleConnectionRecommendations}
        title="Open Connection Recommendations"
        type="button"
      >
        Connect
        {connectionRecommendationCount > 0 ? (
          <span className="ml-0.5 rounded-full bg-cyan-100 px-1.5 py-0.5 text-[10px] font-bold text-cyan-800 shadow-sm ring-1 ring-cyan-200/70">
            {connectionRecommendationCount}
          </span>
        ) : null}
      </button>
      <button
        aria-pressed={isAutoFocusSelectionEnabled}
        className={`${toolbarButtonClass} gap-2 ${isAutoFocusSelectionEnabled ? toolbarActiveButtonClass : ''}`}
        disabled={!session}
        onClick={onToggleAutoFocusSelection}
        title={`Auto-focus selected node family is ${isAutoFocusSelectionEnabled ? 'on' : 'off'}`}
        type="button"
      >
        Focus
        <span
          aria-hidden="true"
          className={`relative inline-flex h-[16px] w-[28px] shrink-0 items-center rounded-full transition ${
            isAutoFocusSelectionEnabled ? 'bg-white/30' : 'bg-slate-300/80'
          }`}
        >
          <span
            className={`absolute top-1/2 h-[12px] w-[12px] -translate-y-1/2 rounded-full bg-white shadow-sm transition-transform ${
              isAutoFocusSelectionEnabled ? 'translate-x-[14px]' : 'translate-x-[2px]'
            }`}
          />
        </span>
      </button>
      <span className={toolbarDividerClass} />
      <button
        aria-label="Generate RCA report"
        className={toolbarIconButtonClass}
        disabled={isWorking || !session || !canGenerateReport}
        onClick={onGenerateReport}
        title={canGenerateReport ? 'Generate RCA report' : 'Select the parent Incident node to generate an RCA report'}
        type="button"
      >
        <FileText aria-hidden="true" size={16} strokeWidth={2.05} />
      </button>
      <span className={toolbarDividerClass} />
      <button
        aria-expanded={isActivityLogOpen}
        aria-label="Open RCA activity log"
        className={`relative ${toolbarIconButtonClass} ${isActivityLogOpen ? toolbarActiveButtonClass : ''}`}
        onClick={onToggleActivityLog}
        title="RCA activity log"
        type="button"
      >
        <ClipboardList aria-hidden="true" size={15} strokeWidth={1.9} />
        {activityLogCount ? (
          <span className="absolute -right-1.5 -top-1.5 grid h-4 min-w-4 place-items-center rounded-full bg-cyan-600 px-1 text-[9px] font-bold leading-none text-white ring-2 ring-white">
            {Math.min(activityLogCount, 99)}
          </span>
        ) : null}
      </button>
      <span className={toolbarDividerClass} />
      <button
        aria-label="Minimize RCA toolbar"
        className={toolbarIconButtonClass}
        onClick={() => setIsToolbarMinimized(true)}
        title="Minimize toolbar"
        type="button"
      >
        <PanelBottomClose aria-hidden="true" size={13} strokeWidth={1.85} />
      </button>
    </div>
  );
}

type RcaReportSection = {
  id: string;
  nodes: RcaNode[];
  subtitle: string;
  title: string;
};

const RCA_REPORT_MODAL_DEFAULT_WIDTH = 920;
const RCA_REPORT_MODAL_DEFAULT_HEIGHT = 760;
const RCA_REPORT_MODAL_MARGIN = 16;

function getRcaReportModalMaxSize(): { height: number; width: number } {
  if (typeof window === 'undefined') {
    return {
      height: RCA_REPORT_MODAL_DEFAULT_HEIGHT,
      width: RCA_REPORT_MODAL_DEFAULT_WIDTH
    };
  }

  return {
    height: Math.max(420, window.innerHeight - RCA_REPORT_MODAL_MARGIN * 2),
    width: Math.max(520, window.innerWidth - RCA_REPORT_MODAL_MARGIN * 2)
  };
}

/**
 * Clearances the maximised report keeps, in pixels.
 *
 * Only a fallback, for when the canvas element cannot be found. Normally the
 * canvas is measured and the report is laid over exactly that area.
 */
const RCA_REPORT_MAXIMIZED_TOP_GAP = 64;
const RCA_REPORT_MAXIMIZED_FOOTER_GAP = 96;

function getInitialRcaReportModalGeometry(): {
  position: { x: number; y: number };
  size: { height: number; width: number };
} {
  const maxSize = getRcaReportModalMaxSize();
  const size = {
    height: Math.min(RCA_REPORT_MODAL_DEFAULT_HEIGHT, maxSize.height),
    width: Math.min(RCA_REPORT_MODAL_DEFAULT_WIDTH, maxSize.width)
  };

  if (typeof window === 'undefined') {
    return {
      position: { x: 72, y: 78 },
      size
    };
  }

  return {
    position: {
      x: Math.max(RCA_REPORT_MODAL_MARGIN, Math.round((window.innerWidth - size.width) / 2)),
      y: Math.max(RCA_REPORT_MODAL_MARGIN, Math.round((window.innerHeight - size.height) / 2))
    },
    size
  };
}

function clampRcaReportModalPosition(
  position: { x: number; y: number },
  size: { height: number; width: number }
): { x: number; y: number } {
  if (typeof window === 'undefined') {
    return position;
  }

  return {
    x: Math.min(
      Math.max(RCA_REPORT_MODAL_MARGIN, position.x),
      Math.max(RCA_REPORT_MODAL_MARGIN, window.innerWidth - size.width - RCA_REPORT_MODAL_MARGIN)
    ),
    y: Math.min(
      Math.max(RCA_REPORT_MODAL_MARGIN, position.y),
      Math.max(RCA_REPORT_MODAL_MARGIN, window.innerHeight - size.height - RCA_REPORT_MODAL_MARGIN)
    )
  };
}

function RcaIncidentReportModal({
  incident,
  incidentNode,
  nodes,
  onClose,
  sessionId
}: {
  incident: RcaIncident;
  incidentNode: RcaNode;
  nodes: RcaNode[];
  onClose: () => void;
  sessionId: string;
}) {
  const [isMaximized, setIsMaximized] = React.useState(false);
  const [maximizedRect, setMaximizedRect] = React.useState<{ height: number; left: number; top: number; width: number } | null>(null);
  const [pageIndex, setPageIndex] = React.useState(0);
  const contentRef = React.useRef<HTMLDivElement | null>(null);
  const [exportStatus, setExportStatus] = React.useState<RcaReportExportFormat | null>(null);
  const [previewUrls, setPreviewUrls] = React.useState<Map<string, string>>(() => new Map());
  const objectUrlsRef = React.useRef<Set<string>>(new Set());
  const initialGeometryRef = React.useRef(getInitialRcaReportModalGeometry());
  const dragStartRef = React.useRef<{
    pointerX: number;
    pointerY: number;
    startX: number;
    startY: number;
  } | null>(null);
  const resizeStartRef = React.useRef<{
    direction: 'width' | 'height' | 'both';
    pointerX: number;
    pointerY: number;
    startHeight: number;
    startWidth: number;
  } | null>(null);
  const [position, setPosition] = React.useState(() => initialGeometryRef.current.position);
  const [size, setSize] = React.useState(() => initialGeometryRef.current.size);
  const reportNodes = React.useMemo(
    () => getRcaIncidentReportNodes(incidentNode, nodes),
    [incidentNode, nodes]
  );
  const reportSections = React.useMemo(
    () => buildRcaIncidentReportSections(reportNodes),
    [reportNodes]
  );
  const evidenceCount = reportNodes.reduce((count, node) => count + node.attachedEvidence.length, 0);
  const generatedAt = React.useMemo(() => new Date().toISOString(), []);

  React.useEffect(() => () => {
    objectUrlsRef.current.forEach((objectUrl) => URL.revokeObjectURL(objectUrl));
    objectUrlsRef.current.clear();
  }, []);

  React.useEffect(() => {
    function handleKeyDown(event: KeyboardEvent) {
      if (event.key === 'Escape') {
        if (isMaximized) {
          setIsMaximized(false);
          return;
        }

        onClose();
      }
    }

    window.addEventListener('keydown', handleKeyDown);
    return () => window.removeEventListener('keydown', handleKeyDown);
  }, [isMaximized, onClose]);

  React.useEffect(() => {
    let isCurrent = true;
    const photoEvidence = reportNodes
      .flatMap((node) => node.attachedEvidence)
      .filter((item) => isImageEvidence(item) && !previewUrls.has(getEvidenceKey(item)));

    if (!photoEvidence.length) {
      return undefined;
    }

    async function hydrateReportThumbnails() {
      const entries = await Promise.all(photoEvidence.map(async (item) => {
        if (isBrowserDisplayableImageUrl(item.fileUrl)) {
          return { key: getEvidenceKey(item), objectUrl: item.fileUrl, shouldRevoke: false };
        }

        if (!isRcaStoredEvidenceUrl(item.fileUrl)) {
          return null;
        }

        try {
          const blob = await downloadRcaEvidenceBlob(incident.id, sessionId, item.fileUrl);
          const objectUrl = URL.createObjectURL(blob);

          return { key: getEvidenceKey(item), objectUrl, shouldRevoke: true };
        } catch {
          return null;
        }
      }));

      if (!isCurrent) {
        entries.forEach((entry) => {
          if (entry?.shouldRevoke) {
            URL.revokeObjectURL(entry.objectUrl);
          }
        });
        return;
      }

      const nextPreviewUrls = new Map(previewUrls);
      let didHydrate = false;

      entries.forEach((entry) => {
        if (!entry) {
          return;
        }

        if (entry.shouldRevoke) {
          objectUrlsRef.current.add(entry.objectUrl);
        }

        nextPreviewUrls.set(entry.key, entry.objectUrl);
        didHydrate = true;
      });

      if (didHydrate) {
        setPreviewUrls(nextPreviewUrls);
      }
    }

    void hydrateReportThumbnails();

    return () => {
      isCurrent = false;
    };
  }, [incident.id, previewUrls, reportNodes, sessionId]);

  React.useEffect(() => {
    function handleMouseMove(event: MouseEvent) {
      const resizeStart = resizeStartRef.current;

      if (resizeStart && !isMaximized) {
        const maxSize = getRcaReportModalMaxSize();
        const minSize = initialGeometryRef.current.size;
        const nextWidth = resizeStart.direction === 'width' || resizeStart.direction === 'both'
          ? resizeStart.startWidth + event.clientX - resizeStart.pointerX
          : resizeStart.startWidth;
        const nextHeight = resizeStart.direction === 'height' || resizeStart.direction === 'both'
          ? resizeStart.startHeight + event.clientY - resizeStart.pointerY
          : resizeStart.startHeight;
        const clampedSize = {
          height: Math.min(Math.max(minSize.height, nextHeight), maxSize.height),
          width: Math.min(Math.max(minSize.width, nextWidth), maxSize.width)
        };

        setSize(clampedSize);
        setPosition((currentPosition) => clampRcaReportModalPosition(currentPosition, clampedSize));
        return;
      }

      const dragStart = dragStartRef.current;

      if (!dragStart || isMaximized) {
        return;
      }

      const nextX = dragStart.startX + event.clientX - dragStart.pointerX;
      const nextY = dragStart.startY + event.clientY - dragStart.pointerY;

      setPosition({
        x: Math.min(Math.max(16, nextX), Math.max(16, window.innerWidth - size.width - 16)),
        y: Math.min(Math.max(16, nextY), Math.max(16, window.innerHeight - size.height - 16))
      });
    }

    function handleMouseUp() {
      dragStartRef.current = null;
      resizeStartRef.current = null;
    }

    window.addEventListener('mousemove', handleMouseMove);
    window.addEventListener('mouseup', handleMouseUp);

    return () => {
      window.removeEventListener('mousemove', handleMouseMove);
      window.removeEventListener('mouseup', handleMouseUp);
    };
  }, [isMaximized, size.height, size.width]);

  React.useEffect(() => {
    function handleWindowResize() {
      const maxSize = getRcaReportModalMaxSize();
      const minSize = initialGeometryRef.current.size;
      const nextSize = {
        height: Math.min(Math.max(minSize.height, size.height), maxSize.height),
        width: Math.min(Math.max(minSize.width, size.width), maxSize.width)
      };

      setSize(nextSize);
      setPosition((currentPosition) => clampRcaReportModalPosition(currentPosition, nextSize));
    }

    window.addEventListener('resize', handleWindowResize);
    return () => window.removeEventListener('resize', handleWindowResize);
  }, [size.height, size.width]);

  async function handleOpenEvidence(item: RcaAttachedEvidence) {
    if (isLikelyUrl(item.fileUrl)) {
      window.open(item.fileUrl, '_blank', 'noopener,noreferrer');
      return;
    }

    if (!isRcaStoredEvidenceUrl(item.fileUrl)) {
      return;
    }

    const evidenceWindow = window.open('', '_blank');

    try {
      const blob = await downloadRcaEvidenceBlob(incident.id, sessionId, item.fileUrl);
      const objectUrl = URL.createObjectURL(blob);

      if (evidenceWindow) {
        evidenceWindow.opener = null;
        evidenceWindow.location.href = objectUrl;
      } else {
        const link = document.createElement('a');
        link.href = objectUrl;
        link.target = '_blank';
        link.rel = 'noreferrer';
        link.download = item.fileName || 'evidence';
        link.click();
      }

      window.setTimeout(() => URL.revokeObjectURL(objectUrl), 60_000);
    } catch {
      evidenceWindow?.close();
    }
  }

  /**
   * Maximised means the canvas area, measured — not the viewport.
   *
   * The canvas already stops short of the side panel on one side and the app
   * footer on the other, so covering it exactly is the whole requirement. The
   * floating control bar sits inside the canvas and is covered along with it;
   * it is not a boundary. Measuring rather than working from constants keeps
   * this right when the side panel collapses or the window is resized.
   */
  const modalStyle = isMaximized
    ? maximizedRect || {
        bottom: RCA_REPORT_MAXIMIZED_FOOTER_GAP,
        left: 'calc(var(--workspace-side-panel-width, 264px) + 12px)',
        right: 12,
        top: RCA_REPORT_MAXIMIZED_TOP_GAP
      }
    : {
        height: size.height,
        left: position.x,
        top: position.y,
        width: size.width
      };
  React.useLayoutEffect(() => {
    if (!isMaximized) {
      setMaximizedRect(null);

      return undefined;
    }

    const canvasArea = document.querySelector('[data-workspace-surface="true"]');

    if (!canvasArea) {
      setMaximizedRect(null);

      return undefined;
    }

    const measure = () => {
      const area = canvasArea.getBoundingClientRect();

      setMaximizedRect({
        height: area.height,
        left: area.left,
        top: area.top,
        width: area.width
      });
    };

    measure();

    const observer = new ResizeObserver(measure);

    observer.observe(canvasArea);
    window.addEventListener('resize', measure);

    return () => {
      observer.disconnect();
      window.removeEventListener('resize', measure);
    };
  }, [isMaximized]);

  const pageCount = reportSections.length;
  const activeSection = reportSections[pageIndex] || null;

  React.useEffect(() => {
    setPageIndex((currentIndex) => Math.min(currentIndex, Math.max(0, pageCount - 1)));
  }, [pageCount]);

  // A new page starts at its heading, not wherever the last one was left scrolled.
  React.useEffect(() => {
    contentRef.current?.scrollTo({ top: 0 });
  }, [pageIndex]);

  const title = incidentNode.label.trim() || incident.title || 'RCA incident report';
  const exportPayload = React.useMemo(
    () => buildRcaReportExportPayload({
      evidenceCount,
      generatedAt,
      incident,
      incidentNode,
      reportNodes,
      reportSections
    }),
    [evidenceCount, generatedAt, incident, incidentNode, reportNodes, reportSections]
  );
  const startResize = (event: React.MouseEvent, direction: 'width' | 'height' | 'both') => {
    if (isMaximized || event.button !== 0) {
      return;
    }

    event.preventDefault();
    event.stopPropagation();
    resizeStartRef.current = {
      direction,
      pointerX: event.clientX,
      pointerY: event.clientY,
      startHeight: size.height,
      startWidth: size.width
    };
  };
  const handleExport = async (format: RcaReportExportFormat) => {
    setExportStatus(format);

    try {
      await exportRcaReport(exportPayload, format, previewUrls);
    } finally {
      setExportStatus(null);
    }
  };

  return createPortal(
    <section
      aria-label="RCA report preview"
      className={`fixed z-[130] flex flex-col overflow-hidden border border-slate-200 bg-white text-slate-950 shadow-[0_28px_90px_rgba(15,23,42,0.28),0_8px_28px_rgba(14,165,233,0.12)] ring-1 ring-slate-950/5 ${
        isMaximized ? 'rounded-lg' : 'rounded-lg'
      }`}
      role="dialog"
      style={modalStyle}
    >
      {!isMaximized ? (
        <>
          <div
            aria-hidden="true"
            className="absolute bottom-5 right-0 top-5 z-20 w-2 cursor-ew-resize bg-transparent transition hover:bg-cyan-400/20 active:bg-cyan-400/30"
            onMouseDown={(event) => startResize(event, 'width')}
          />
          <div
            aria-hidden="true"
            className="absolute bottom-0 left-5 right-5 z-20 h-2 cursor-ns-resize bg-transparent transition hover:bg-cyan-400/20 active:bg-cyan-400/30"
            onMouseDown={(event) => startResize(event, 'height')}
          />
          <div
            aria-hidden="true"
            className="absolute bottom-0 right-0 z-30 h-5 w-5 cursor-nwse-resize rounded-tl-xl bg-transparent transition hover:bg-cyan-400/20 active:bg-cyan-400/30"
            onMouseDown={(event) => startResize(event, 'both')}
          />
        </>
      ) : null}

      <header
        className={`flex shrink-0 items-center justify-between gap-4 border-b border-slate-200 bg-white px-5 py-4 ${
          isMaximized ? '' : 'cursor-move'
        }`}
        onMouseDown={(event) => {
          if (isMaximized || event.button !== 0) {
            return;
          }

          dragStartRef.current = {
            pointerX: event.clientX,
            pointerY: event.clientY,
            startX: position.x,
            startY: position.y
          };
        }}
      >
        <div className="min-w-0">
          <p className="text-[10px] font-medium uppercase tracking-[0.12em] text-cyan-700">RCA Report</p>
          <h2 className="mt-1 truncate text-lg font-medium tracking-tight text-slate-900">{title}</h2>
          <p className="mt-1 truncate text-xs text-slate-500">
            {incident.displayId || buildFriendlyRcaDisplayId('RCA', incident.id, incident.createdAtIso)} • {reportNodes.length} node{reportNodes.length === 1 ? '' : 's'} • {evidenceCount} evidence item{evidenceCount === 1 ? '' : 's'}
          </p>
        </div>
        <div className="flex items-center gap-2">
          <Popover.Root>
            <Popover.Trigger asChild>
              <button
                className="inline-flex h-9 items-center justify-center gap-2 rounded-md border border-slate-300 bg-white px-3 text-xs font-medium text-slate-700 transition hover:border-slate-400 hover:bg-slate-50 active:bg-slate-100 disabled:cursor-not-allowed disabled:opacity-55"
                disabled={Boolean(exportStatus)}
                onMouseDown={(event) => event.stopPropagation()}
                title="Export RCA report"
                type="button"
              >
                <FileDown aria-hidden="true" size={16} strokeWidth={2} />
                Export
              </button>
            </Popover.Trigger>
            <Popover.Portal>
              <Popover.Content
                align="end"
                className="z-[160] w-56 rounded-lg border border-slate-200 bg-white p-1 text-slate-700 shadow-[0_8px_16px_rgba(0,0,0,0.14),0_0_2px_rgba(0,0,0,0.12)]"
                onMouseDown={(event) => event.stopPropagation()}
                sideOffset={8}
              >
                <RcaReportExportMenuItem
                  disabled={Boolean(exportStatus)}
                  icon={FileText}
                  isLoading={exportStatus === 'word'}
                  label="MS Word"
                  onClick={() => void handleExport('word')}
                />
                <RcaReportExportMenuItem
                  disabled={Boolean(exportStatus)}
                  icon={FileText}
                  isLoading={exportStatus === 'pdf'}
                  label="PDF"
                  onClick={() => void handleExport('pdf')}
                />
                <RcaReportExportMenuItem
                  disabled={Boolean(exportStatus)}
                  icon={Presentation}
                  isLoading={exportStatus === 'powerpoint'}
                  label="PowerPoint"
                  onClick={() => void handleExport('powerpoint')}
                />
                <RcaReportExportMenuItem
                  disabled={Boolean(exportStatus)}
                  icon={FileSpreadsheet}
                  isLoading={exportStatus === 'excel'}
                  label="Excel"
                  onClick={() => void handleExport('excel')}
                />
                <Popover.Arrow className="fill-white" />
              </Popover.Content>
            </Popover.Portal>
          </Popover.Root>
          <button
            className="grid h-9 w-9 place-items-center rounded-md border border-slate-300 bg-white text-slate-600 transition hover:border-slate-400 hover:bg-slate-50 active:bg-slate-100"
            onClick={() => setIsMaximized((currentValue) => !currentValue)}
            title={isMaximized ? 'Restore report' : 'Maximize report'}
            type="button"
          >
            {isMaximized ? <Minimize2 aria-hidden="true" size={17} /> : <Maximize2 aria-hidden="true" size={17} />}
          </button>
          <button
            className="grid h-9 w-9 place-items-center rounded-md border border-slate-300 bg-white text-slate-600 transition hover:border-red-300 hover:bg-red-50 hover:text-red-600"
            onClick={onClose}
            title="Close report"
            type="button"
          >
            <X aria-hidden="true" size={18} />
          </button>
        </div>
      </header>

      <div className="min-h-0 flex-1 overflow-y-auto bg-white px-8 py-6" ref={contentRef}>
        <dl className="grid grid-cols-1 gap-x-10 gap-y-4 border-b border-slate-300 pb-5 sm:grid-cols-3">
          <div>
            <dt className="text-[11px] font-medium uppercase tracking-[0.08em] text-slate-500">Project</dt>
            <dd className="mt-1.5 text-sm leading-6 text-slate-900">{incident.title || 'Untitled RCA project'}</dd>
          </div>
          <div>
            <dt className="text-[11px] font-medium uppercase tracking-[0.08em] text-slate-500">Status</dt>
            <dd className="mt-1.5 text-sm leading-6 text-slate-900">{formatStatus(incident.status || 'ACTIVE')}</dd>
          </div>
          <div>
            <dt className="text-[11px] font-medium uppercase tracking-[0.08em] text-slate-500">Generated</dt>
            <dd className="mt-1.5 text-sm leading-6 text-slate-900">{formatAuditDate(generatedAt)}</dd>
          </div>
        </dl>

        {activeSection ? (
          <section className="pt-6" key={activeSection.id}>
            <div className="border-b border-slate-300 pb-3">
              <h3 className="text-sm font-medium uppercase tracking-[0.08em] text-slate-900">{activeSection.title}</h3>
              <p className="mt-1 text-xs leading-5 text-slate-500">{activeSection.subtitle}</p>
            </div>
            <div className="divide-y divide-slate-200">
              {activeSection.nodes.map((node) => (
                <RcaIncidentReportNodeCard
                  key={node.id}
                  node={node}
                  onOpenEvidence={handleOpenEvidence}
                  previewUrls={previewUrls}
                />
              ))}
            </div>
          </section>
        ) : (
          <p className="py-16 text-center text-sm text-slate-500">This report has no sections yet.</p>
        )}
      </div>

      <footer className="flex shrink-0 items-center justify-between gap-4 border-t border-slate-200 bg-white px-6 py-3">
        <p className="min-w-0 truncate text-xs text-slate-500">
          {activeSection ? activeSection.title : 'Preview only.'}
        </p>
        <div className="flex shrink-0 items-center gap-1">
          <button
            className="inline-flex h-9 items-center gap-1 rounded-md border border-slate-300 bg-white px-3 text-xs font-medium text-slate-700 transition hover:border-slate-400 hover:bg-slate-50 disabled:cursor-not-allowed disabled:opacity-40"
            disabled={pageIndex <= 0}
            onClick={() => setPageIndex((currentIndex) => Math.max(0, currentIndex - 1))}
            type="button"
          >
            <ChevronLeft aria-hidden="true" size={15} strokeWidth={1.75} />
            Previous
          </button>
          <p aria-live="polite" className="px-3 text-xs tabular-nums text-slate-600">
            Page {pageCount ? pageIndex + 1 : 0} of {pageCount}
          </p>
          <button
            className="inline-flex h-9 items-center gap-1 rounded-md border border-slate-300 bg-white px-3 text-xs font-medium text-slate-700 transition hover:border-slate-400 hover:bg-slate-50 disabled:cursor-not-allowed disabled:opacity-40"
            disabled={pageIndex >= pageCount - 1}
            onClick={() => setPageIndex((currentIndex) => Math.min(pageCount - 1, currentIndex + 1))}
            type="button"
          >
            Next
            <ChevronRight aria-hidden="true" size={15} strokeWidth={1.75} />
          </button>
          <button
            className="ml-2 inline-flex h-9 items-center justify-center rounded-md bg-slate-900 px-4 text-sm font-medium text-white transition hover:bg-slate-700 active:bg-slate-800"
            onClick={onClose}
            type="button"
          >
            Close
          </button>
        </div>
      </footer>
    </section>,
    document.body
  );
}

type RcaReportExportFormat = 'excel' | 'pdf' | 'powerpoint' | 'word';

interface RcaReportExportEvidence {
  fileName: string;
  fileUrl: string;
  key: string;
  uploadedAt: string;
}

interface RcaReportExportNode {
  evidence: RcaReportExportEvidence[];
  fields: Array<{ label: string; value: string }>;
  id: string;
  status: string;
  title: string;
  type: string;
}

interface RcaReportExportSection {
  nodes: RcaReportExportNode[];
  subtitle: string;
  title: string;
}

interface RcaReportExportPayload {
  displayId: string;
  evidenceCount: number;
  fileBaseName: string;
  generatedAt: string;
  generatedAtLabel: string;
  incidentTitle: string;
  nodeCount: number;
  projectTitle: string;
  sections: RcaReportExportSection[];
  status: string;
}

function RcaReportExportMenuItem({
  disabled,
  icon: Icon,
  isLoading,
  label,
  onClick
}: {
  disabled: boolean;
  icon: LucideIcon;
  isLoading: boolean;
  label: string;
  onClick: () => void;
}) {
  return (
    <button
      className="flex h-10 w-full items-center gap-3 rounded-xl px-3 text-left text-sm font-medium text-slate-700 transition hover:bg-cyan-50 hover:text-cyan-800 disabled:cursor-not-allowed disabled:opacity-55"
      disabled={disabled}
      onClick={onClick}
      type="button"
    >
      <span className="grid h-7 w-7 place-items-center rounded-lg bg-slate-50 text-cyan-700 ring-1 ring-slate-200">
        <Icon aria-hidden="true" size={16} strokeWidth={2} />
      </span>
      <span className="min-w-0 flex-1">{label}</span>
      {isLoading ? <span className="h-2 w-2 animate-pulse rounded-full bg-cyan-600" /> : null}
    </button>
  );
}

function buildRcaReportExportPayload({
  evidenceCount,
  generatedAt,
  incident,
  incidentNode,
  reportNodes,
  reportSections
}: {
  evidenceCount: number;
  generatedAt: string;
  incident: RcaIncident;
  incidentNode: RcaNode;
  reportNodes: RcaNode[];
  reportSections: RcaReportSection[];
}): RcaReportExportPayload {
  const incidentTitle = incidentNode.label.trim() || incident.title || 'RCA Incident Report';
  const displayId = incident.displayId || buildFriendlyRcaDisplayId('RCA', incident.id, incident.createdAtIso);

  return {
    displayId,
    evidenceCount,
    fileBaseName: sanitizeRcaExportFileName(`${displayId}-${incidentTitle}`),
    generatedAt,
    generatedAtLabel: formatAuditDate(generatedAt),
    incidentTitle,
    nodeCount: reportNodes.length,
    projectTitle: incident.title || 'Untitled RCA project',
    sections: reportSections.map((section) => ({
      nodes: section.nodes.map((node) => {
        const role = node.nodeType === 'WHY' ? getFiveWhysNodeRole(node) : null;
        const status = node.isRootCause ? 'Verified cause' : node.isSuspectedCause ? 'Suspect' : '';

        return {
          evidence: node.attachedEvidence.map((item) => ({
            fileName: item.fileName || 'Evidence file',
            fileUrl: isLikelyUrl(item.fileUrl) ? item.fileUrl : '',
            key: getEvidenceKey(item),
            uploadedAt: item.uploadedAtIso ? formatAuditDate(item.uploadedAtIso) : 'Attached evidence'
          })),
          fields: getRcaReportFieldEntries(node).map((entry) => ({
            label: entry.label,
            value: entry.value
          })),
          id: node.id,
          status,
          title: getRcaReportNodeTitle(node),
          type: role ? getFiveWhysRoleLabel(role) : formatNodeType(node.nodeType)
        };
      }),
      subtitle: section.subtitle,
      title: section.title
    })),
    status: formatStatus(incident.status || 'ACTIVE')
  };
}

async function exportRcaReport(
  payload: RcaReportExportPayload,
  format: RcaReportExportFormat,
  previewUrls: Map<string, string>
) {
  if (format === 'word') {
    await exportRcaReportToWord(payload);
    return;
  }

  if (format === 'pdf') {
    await exportRcaReportToPdf(payload, previewUrls);
    return;
  }

  if (format === 'powerpoint') {
    await exportRcaReportToPowerPoint(payload, previewUrls);
    return;
  }

  await exportRcaReportToExcel(payload);
}

async function exportRcaReportToWord(payload: RcaReportExportPayload) {
  const {
    BorderStyle,
    Document,
    HeadingLevel,
    Packer,
    Paragraph,
    Table,
    TableCell,
    TableRow,
    TextRun,
    WidthType
  } = await import('docx');
  const border = {
    bottom: { color: 'E2E8F0', size: 1, style: BorderStyle.SINGLE },
    left: { color: 'E2E8F0', size: 1, style: BorderStyle.SINGLE },
    right: { color: 'E2E8F0', size: 1, style: BorderStyle.SINGLE },
    top: { color: 'E2E8F0', size: 1, style: BorderStyle.SINGLE }
  };
  const paragraphs = [
    new Paragraph({
      children: [new TextRun({ color: '0369A1', size: 18, text: 'RCA REPORT' })],
      spacing: { after: 120 }
    }),
    new Paragraph({
      children: [new TextRun({ bold: true, size: 30, text: payload.incidentTitle })],
      heading: HeadingLevel.TITLE,
      spacing: { after: 120 }
    }),
    new Paragraph({
      children: [new TextRun({ color: '475569', size: 20, text: `${payload.displayId} • ${payload.nodeCount} nodes • ${payload.evidenceCount} evidence items` })],
      spacing: { after: 240 }
    }),
    buildDocxMetaTable(payload, { Table, TableCell, TableRow, TextRun, Paragraph, WidthType, border })
  ];

  payload.sections.forEach((section) => {
    paragraphs.push(
      new Paragraph({
        children: [new TextRun({ bold: true, color: '0369A1', size: 22, text: section.title })],
        heading: HeadingLevel.HEADING_1,
        spacing: { before: 280, after: 80 }
      }),
      new Paragraph({
        children: [new TextRun({ color: '475569', size: 19, text: section.subtitle })],
        spacing: { after: 140 }
      })
    );

    section.nodes.forEach((node) => {
      paragraphs.push(
        new Paragraph({
          children: [new TextRun({ bold: true, color: '0F172A', size: 21, text: `${node.type}: ${node.title}` })],
          spacing: { before: 80, after: 80 }
        })
      );

      if (node.fields.length) {
        paragraphs.push(buildDocxFieldsTable(node, { Table, TableCell, TableRow, TextRun, Paragraph, WidthType, border }));
      }

      if (node.evidence.length) {
        paragraphs.push(new Paragraph({
          children: [new TextRun({ bold: true, color: '0369A1', size: 18, text: 'Evidence' })],
          spacing: { before: 120, after: 40 }
        }));
        node.evidence.forEach((item) => {
          paragraphs.push(new Paragraph({
            children: [new TextRun({ color: '334155', size: 18, text: `${item.fileName} • ${item.uploadedAt}${item.fileUrl ? ` • ${item.fileUrl}` : ''}` })],
            spacing: { after: 40 }
          }));
        });
      }
    });
  });

  const doc = new Document({
    sections: [{
      children: paragraphs,
      properties: {
        page: {
          margin: { bottom: 720, left: 720, right: 720, top: 720 }
        }
      }
    }]
  });
  const blob = await Packer.toBlob(doc);
  downloadRcaReportBlob(blob, `${payload.fileBaseName}.docx`);
}

function buildDocxMetaTable(
  payload: RcaReportExportPayload,
  docx: {
    Paragraph: any;
    Table: any;
    TableCell: any;
    TableRow: any;
    TextRun: any;
    WidthType: any;
    border: any;
  }
) {
  return new docx.Table({
    borders: docx.border,
    rows: [
      new docx.TableRow({
        children: [
          buildDocxCell('Project', payload.projectTitle, docx),
          buildDocxCell('Status', payload.status, docx),
          buildDocxCell('Generated', payload.generatedAtLabel, docx)
        ]
      })
    ],
    width: { size: 100, type: docx.WidthType.PERCENTAGE }
  });
}

function buildDocxFieldsTable(
  node: RcaReportExportNode,
  docx: {
    Paragraph: any;
    Table: any;
    TableCell: any;
    TableRow: any;
    TextRun: any;
    WidthType: any;
    border: any;
  }
) {
  const rows: any[] = [];

  for (let index = 0; index < node.fields.length; index += 2) {
    rows.push(new docx.TableRow({
      children: [
        buildDocxCell(node.fields[index].label, node.fields[index].value, docx),
        node.fields[index + 1]
          ? buildDocxCell(node.fields[index + 1].label, node.fields[index + 1].value, docx)
          : buildDocxCell('', '', docx)
      ]
    }));
  }

  return new docx.Table({
    borders: docx.border,
    rows,
    width: { size: 100, type: docx.WidthType.PERCENTAGE }
  });
}

function buildDocxCell(label: string, value: string, docx: { Paragraph: any; TableCell: any; TextRun: any }) {
  return new docx.TableCell({
    children: [
      new docx.Paragraph({
        children: [new docx.TextRun({ color: '64748B', size: 15, text: label.toUpperCase() })],
        spacing: { after: 60 }
      }),
      new docx.Paragraph({
        children: [new docx.TextRun({ color: '0F172A', size: 18, text: value || 'Not provided' })]
      })
    ],
    margins: { bottom: 140, left: 140, right: 140, top: 140 }
  });
}

async function exportRcaReportToPdf(payload: RcaReportExportPayload, previewUrls: Map<string, string>) {
  const { default: JsPDF } = await import('jspdf');
  const pdf = new JsPDF({ unit: 'pt', format: 'letter' });
  const pageWidth = pdf.internal.pageSize.getWidth();
  const pageHeight = pdf.internal.pageSize.getHeight();
  const margin = 42;
  let y = margin;

  const ensureSpace = (height: number) => {
    if (y + height <= pageHeight - margin) {
      return;
    }

    pdf.addPage();
    y = margin;
  };
  const writeText = (text: string, x: number, width: number, options: { color?: [number, number, number]; size?: number; style?: 'bold' | 'normal' } = {}) => {
    pdf.setFont('helvetica', options.style || 'normal');
    pdf.setFontSize(options.size || 10);
    pdf.setTextColor(...(options.color || [15, 23, 42]));
    const lines = pdf.splitTextToSize(text || 'Not provided', width);
    pdf.text(lines, x, y);
    y += lines.length * ((options.size || 10) + 4);
  };

  pdf.setFillColor(248, 250, 252);
  pdf.rect(0, 0, pageWidth, pageHeight, 'F');
  writeText('RCA REPORT', margin, pageWidth - margin * 2, { color: [3, 105, 161], size: 9, style: 'bold' });
  y += 4;
  writeText(payload.incidentTitle, margin, pageWidth - margin * 2, { size: 18, style: 'bold' });
  writeText(`${payload.displayId} • ${payload.nodeCount} nodes • ${payload.evidenceCount} evidence items`, margin, pageWidth - margin * 2, { color: [71, 85, 105], size: 10 });
  y += 14;
  drawPdfMetaCards(pdf, payload, margin, y, pageWidth - margin * 2);
  y += 62;

  for (const section of payload.sections) {
    ensureSpace(80);
    y += 14;
    writeText(section.title, margin, pageWidth - margin * 2, { color: [3, 105, 161], size: 11, style: 'bold' });
    writeText(section.subtitle, margin, pageWidth - margin * 2, { color: [71, 85, 105], size: 9 });
    y += 6;

    for (const node of section.nodes) {
      ensureSpace(110);
      const cardTop = y;
      pdf.setDrawColor(226, 232, 240);
      pdf.setFillColor(255, 255, 255);
      pdf.roundedRect(margin, cardTop, pageWidth - margin * 2, 70, 10, 10, 'FD');
      y += 18;
      writeText(`${node.type}${node.status ? ` • ${node.status}` : ''}`, margin + 14, pageWidth - margin * 2 - 28, { color: [3, 105, 161], size: 8, style: 'bold' });
      writeText(node.title, margin + 14, pageWidth - margin * 2 - 28, { size: 10, style: 'bold' });
      y = Math.max(y + 8, cardTop + 76);

      node.fields.forEach((field) => {
        ensureSpace(34);
        writeText(`${field.label}: ${field.value}`, margin + 16, pageWidth - margin * 2 - 32, { color: [51, 65, 85], size: 9 });
      });

      if (node.evidence.length) {
        ensureSpace(38);
        writeText('Evidence', margin + 16, pageWidth - margin * 2 - 32, { color: [3, 105, 161], size: 9, style: 'bold' });
        for (const evidence of node.evidence) {
          ensureSpace(48);
          const previewUrl = previewUrls.get(evidence.key);

          if (previewUrl) {
            const imageData = await toImageDataUrl(previewUrl);

            if (imageData) {
              pdf.addImage(imageData, getPdfImageFormat(imageData), margin + 16, y - 4, 42, 32, undefined, 'FAST');
              writeText(`${evidence.fileName} • ${evidence.uploadedAt}`, margin + 66, pageWidth - margin * 2 - 82, { color: [51, 65, 85], size: 8 });
              y += 8;
              continue;
            }
          }

          writeText(`${evidence.fileName} • ${evidence.uploadedAt}`, margin + 20, pageWidth - margin * 2 - 40, { color: [51, 65, 85], size: 8 });
        }
      }
    }
  }

  pdf.save(`${payload.fileBaseName}.pdf`);
}

function drawPdfMetaCards(pdf: any, payload: RcaReportExportPayload, x: number, y: number, width: number) {
  const gap = 10;
  const cardWidth = (width - gap * 2) / 3;
  const cards = [
    ['Project', payload.projectTitle],
    ['Status', payload.status],
    ['Generated', payload.generatedAtLabel]
  ];

  cards.forEach(([label, value], index) => {
    const cardX = x + index * (cardWidth + gap);
    pdf.setDrawColor(226, 232, 240);
    pdf.setFillColor(255, 255, 255);
    pdf.roundedRect(cardX, y, cardWidth, 52, 10, 10, 'FD');
    pdf.setFont('helvetica', 'bold');
    pdf.setFontSize(7);
    pdf.setTextColor(100, 116, 139);
    pdf.text(label.toUpperCase(), cardX + 12, y + 18);
    pdf.setFont('helvetica', 'normal');
    pdf.setFontSize(9);
    pdf.setTextColor(15, 23, 42);
    pdf.text(pdf.splitTextToSize(value, cardWidth - 24), cardX + 12, y + 34);
  });
}

async function exportRcaReportToPowerPoint(payload: RcaReportExportPayload, previewUrls: Map<string, string>) {
  const { default: pptxgen } = await import('pptxgenjs');
  const pptx = new pptxgen();
  pptx.layout = 'LAYOUT_WIDE';
  pptx.author = 'Synzapp RCA';
  pptx.subject = payload.incidentTitle;
  pptx.title = payload.incidentTitle;
  pptx.company = 'Synzapp';
  pptx.theme = {
    headFontFace: 'Aptos Display',
    bodyFontFace: 'Aptos'
  };

  const titleSlide = pptx.addSlide();
  titleSlide.background = { color: 'F8FAFC' };
  titleSlide.addText('RCA REPORT', { x: 0.6, y: 0.55, w: 3, h: 0.25, fontSize: 10, bold: true, color: '0369A1' });
  titleSlide.addText(payload.incidentTitle, { x: 0.6, y: 0.95, w: 11.8, h: 0.7, fontSize: 24, bold: true, color: '0F172A', fit: 'shrink' });
  titleSlide.addText(`${payload.displayId} • ${payload.nodeCount} nodes • ${payload.evidenceCount} evidence items`, { x: 0.6, y: 1.75, w: 11, h: 0.3, fontSize: 11, color: '475569' });
  addPptMetaCard(titleSlide, 'Project', payload.projectTitle, 0.6, 2.45);
  addPptMetaCard(titleSlide, 'Status', payload.status, 4.6, 2.45);
  addPptMetaCard(titleSlide, 'Generated', payload.generatedAtLabel, 8.6, 2.45);

  for (const section of payload.sections) {
    const slide = pptx.addSlide();
    slide.background = { color: 'F8FAFC' };
    slide.addText(section.title, { x: 0.55, y: 0.42, w: 12.2, h: 0.34, fontSize: 13, bold: true, color: '0369A1' });
    slide.addText(section.subtitle, { x: 0.55, y: 0.82, w: 12, h: 0.3, fontSize: 10, color: '475569' });
    let y = 1.25;

    for (const node of section.nodes.slice(0, 4)) {
      slide.addShape(pptx.ShapeType.roundRect, { x: 0.55, y, w: 12.2, h: 1.05, rectRadius: 0.08, fill: { color: 'FFFFFF' }, line: { color: 'E2E8F0', width: 1 } });
      slide.addText(node.type, { x: 0.78, y: y + 0.15, w: 2.1, h: 0.18, fontSize: 7.5, bold: true, color: '64748B' });
      slide.addText(node.title, { x: 0.78, y: y + 0.38, w: 5.1, h: 0.46, fontSize: 10.5, bold: true, color: '0F172A', fit: 'shrink' });
      const fields = node.fields.slice(0, 4).map((field) => `${field.label}: ${field.value}`).join('\n');
      slide.addText(fields || 'No structured fields recorded.', { x: 6.05, y: y + 0.18, w: 4.3, h: 0.66, fontSize: 7.8, color: '334155', fit: 'shrink', breakLine: false });
      const firstImageEvidence = node.evidence.find((item) => previewUrls.has(item.key));

      if (firstImageEvidence) {
        const imageData = await toImageDataUrl(previewUrls.get(firstImageEvidence.key) || '');

        if (imageData) {
          slide.addImage({ data: imageData, x: 10.55, y: y + 0.16, w: 1.75, h: 0.72 });
        }
      } else if (node.evidence.length) {
        slide.addText(`${node.evidence.length} evidence item${node.evidence.length === 1 ? '' : 's'}`, { x: 10.55, y: y + 0.38, w: 1.75, h: 0.24, fontSize: 8, color: '0369A1' });
      }

      y += 1.22;
    }

    if (section.nodes.length > 4) {
      slide.addText(`+ ${section.nodes.length - 4} additional item${section.nodes.length - 4 === 1 ? '' : 's'} in this section`, { x: 0.7, y: 6.35, w: 5, h: 0.24, fontSize: 9, color: '64748B' });
    }
  }

  await pptx.writeFile({ fileName: `${payload.fileBaseName}.pptx` });
}

function addPptMetaCard(slide: any, label: string, value: string, x: number, y: number) {
  slide.addShape('roundRect', { x, y, w: 3.45, h: 0.8, rectRadius: 0.08, fill: { color: 'FFFFFF' }, line: { color: 'E2E8F0', width: 1 } });
  slide.addText(label.toUpperCase(), { x: x + 0.18, y: y + 0.14, w: 3, h: 0.16, fontSize: 7.5, color: '64748B', bold: true });
  slide.addText(value, { x: x + 0.18, y: y + 0.4, w: 3.05, h: 0.24, fontSize: 10.5, color: '0F172A', fit: 'shrink' });
}

async function exportRcaReportToExcel(payload: RcaReportExportPayload) {
  const XLSX = await import('xlsx');
  const workbook = XLSX.utils.book_new();
  const summaryRows = [
    ['RCA Report', payload.incidentTitle],
    ['RCA ID', payload.displayId],
    ['Project', payload.projectTitle],
    ['Status', payload.status],
    ['Generated', payload.generatedAtLabel],
    ['Nodes', payload.nodeCount],
    ['Evidence items', payload.evidenceCount]
  ];
  const summarySheet = XLSX.utils.aoa_to_sheet(summaryRows);
  summarySheet['!cols'] = [{ wch: 20 }, { wch: 90 }];
  XLSX.utils.book_append_sheet(workbook, summarySheet, 'Summary');

  const nodeRows = payload.sections.flatMap((section) => section.nodes.map((node) => ({
    Section: section.title,
    Type: node.type,
    Title: node.title,
    Status: node.status,
    Fields: node.fields.map((field) => `${field.label}: ${field.value}`).join('\n'),
    Evidence: node.evidence.map((item) => `${item.fileName} (${item.uploadedAt})${item.fileUrl ? ` - ${item.fileUrl}` : ''}`).join('\n')
  })));
  const nodeSheet = XLSX.utils.json_to_sheet(nodeRows);
  nodeSheet['!cols'] = [
    { wch: 32 },
    { wch: 22 },
    { wch: 58 },
    { wch: 16 },
    { wch: 90 },
    { wch: 80 }
  ];
  XLSX.utils.book_append_sheet(workbook, nodeSheet, 'RCA Flow');

  const evidenceRows = payload.sections.flatMap((section) => section.nodes.flatMap((node) => node.evidence.map((item) => ({
    Section: section.title,
    NodeType: node.type,
    NodeTitle: node.title,
    FileName: item.fileName,
    AttachedAt: item.uploadedAt,
    Link: item.fileUrl
  }))));
  const evidenceSheet = XLSX.utils.json_to_sheet(evidenceRows.length ? evidenceRows : [{ Section: '', NodeType: '', NodeTitle: '', FileName: 'No evidence attached', AttachedAt: '', Link: '' }]);
  evidenceSheet['!cols'] = [
    { wch: 32 },
    { wch: 22 },
    { wch: 58 },
    { wch: 42 },
    { wch: 24 },
    { wch: 70 }
  ];
  XLSX.utils.book_append_sheet(workbook, evidenceSheet, 'Evidence');
  XLSX.writeFile(workbook, `${payload.fileBaseName}.xlsx`, { compression: true });
}

function downloadRcaReportBlob(blob: Blob, fileName: string) {
  const objectUrl = URL.createObjectURL(blob);
  const link = document.createElement('a');

  link.href = objectUrl;
  link.download = fileName;
  document.body.appendChild(link);
  link.click();
  link.remove();
  window.setTimeout(() => URL.revokeObjectURL(objectUrl), 1000);
}

function sanitizeRcaExportFileName(value: string) {
  const cleanValue = value
    .replace(/[^a-z0-9._-]+/gi, '-')
    .replace(/-+/g, '-')
    .replace(/^-|-$/g, '')
    .slice(0, 120);

  return cleanValue || 'RCA-report';
}

async function toImageDataUrl(sourceUrl: string): Promise<string | null> {
  if (!sourceUrl) {
    return null;
  }

  try {
    const response = await fetch(sourceUrl);
    const blob = await response.blob();

    return await new Promise((resolve) => {
      const reader = new FileReader();

      reader.onload = () => resolve(typeof reader.result === 'string' ? reader.result : null);
      reader.onerror = () => resolve(null);
      reader.readAsDataURL(blob);
    });
  } catch {
    return null;
  }
}

function getPdfImageFormat(dataUrl: string): 'JPEG' | 'PNG' | 'WEBP' {
  if (/^data:image\/png/i.test(dataUrl)) {
    return 'PNG';
  }

  if (/^data:image\/webp/i.test(dataUrl)) {
    return 'WEBP';
  }

  return 'JPEG';
}

/**
 * A long answer takes the full width of the report.
 *
 * Descriptions and impact statements run to several lines. Held in one half of a
 * two column grid they wrap into a narrow ribbon while the cell beside them sits
 * empty, which is what stranded the incident description. Past this length, or
 * once the text carries its own line breaks, the field takes the whole row and
 * reads as a paragraph.
 */
const RCA_REPORT_WIDE_FIELD_CHARACTERS = 110;

function isWideRcaReportFieldValue(value: string): boolean {
  return value.length > RCA_REPORT_WIDE_FIELD_CHARACTERS || value.includes('\n');
}

function RcaIncidentReportNodeCard({
  node,
  onOpenEvidence,
  previewUrls
}: {
  node: RcaNode;
  onOpenEvidence: (item: RcaAttachedEvidence) => void;
  previewUrls: Map<string, string>;
}) {
  const role = node.nodeType === 'WHY' ? getFiveWhysNodeRole(node) : null;
  const fieldEntries = getRcaReportFieldEntries(node);
  const title = getRcaReportNodeTitle(node);

  return (
    <article className="py-5">
      <div className="flex items-start justify-between gap-3 border-b border-slate-200 pb-3">
        <div className="min-w-0">
          <span className="inline-flex rounded bg-slate-100 px-2 py-0.5 text-[10px] font-medium uppercase tracking-[0.08em] text-slate-600">
            {role ? getFiveWhysRoleLabel(role) : formatNodeType(node.nodeType)}
          </span>
          <h3 className="mt-2 whitespace-pre-wrap text-[15px] font-medium leading-6 text-slate-900">{title}</h3>
        </div>
        {node.isRootCause ? (
          <span className="shrink-0 rounded border border-red-200 bg-red-50 px-2 py-0.5 text-[10px] font-medium uppercase tracking-[0.08em] text-red-700">
            Cause
          </span>
        ) : node.isSuspectedCause ? (
          <span className="shrink-0 rounded border border-amber-200 bg-amber-50 px-2 py-0.5 text-[10px] font-medium uppercase tracking-[0.08em] text-amber-700">
            Suspect
          </span>
        ) : null}
      </div>

      {fieldEntries.length ? (
        <dl className="mt-1 grid grid-cols-1 gap-x-10 md:grid-cols-2">
          {fieldEntries.map((entry) => (
            <div
              className={`border-b border-slate-100 py-2.5 ${isWideRcaReportFieldValue(entry.value) ? 'md:col-span-2' : ''}`}
              key={entry.key}
            >
              <dt className="text-[11px] font-medium uppercase tracking-[0.08em] text-slate-500">{entry.label}</dt>
              <dd className="mt-1 whitespace-pre-wrap text-sm leading-6 text-slate-900">{entry.value}</dd>
            </div>
          ))}
        </dl>
      ) : null}

      {node.attachedEvidence.length ? (
        <div className="mt-4">
          <p className="mb-2 text-[10px] font-medium uppercase tracking-[0.1em] text-slate-500">Evidence</p>
          <div className="grid gap-2 sm:grid-cols-2 lg:grid-cols-3">
            {node.attachedEvidence.map((item) => {
              const previewUrl = getEvidencePreviewUrl(item, previewUrls);

              return (
                <button
                  className="overflow-hidden rounded-md border border-slate-200 bg-white text-left transition hover:border-slate-400 hover:bg-slate-50"
                  key={getEvidenceKey(item)}
                  onClick={() => onOpenEvidence(item)}
                  type="button"
                >
                  {previewUrl ? (
                    <img alt="" className="h-24 w-full bg-slate-100 object-cover" src={previewUrl} />
                  ) : (
                    <div className="grid h-24 place-items-center bg-slate-50 text-cyan-700">
                      {isLikelyUrl(item.fileUrl) ? <Link2 aria-hidden="true" size={22} /> : <FileLock2 aria-hidden="true" size={22} />}
                    </div>
                  )}
                  <div className="p-2">
                    <p className="truncate text-xs text-slate-900">{item.fileName || 'Evidence file'}</p>
                    <p className="mt-1 text-[11px] text-slate-500">
                      {item.uploadedAtIso ? formatAuditDate(item.uploadedAtIso) : 'Attached evidence'}
                    </p>
                  </div>
                </button>
              );
            })}
          </div>
        </div>
      ) : null}
    </article>
  );
}

function RcaCanvasControlButtons({
  interactionMode,
  isSnapEnabled,
  onInteractionModeChange,
  onSnapToggle
}: {
  interactionMode: RcaCanvasInteractionMode;
  isSnapEnabled: boolean;
  onInteractionModeChange: (mode: RcaCanvasInteractionMode) => void;
  onSnapToggle: () => void;
}) {
  const activeControlClassName = '!bg-cyan-600 !text-white';

  return (
    <>
      <ControlButton
        aria-label="Select nodes"
        aria-pressed={interactionMode === 'select'}
        className={interactionMode === 'select' ? activeControlClassName : undefined}
        onClick={() => onInteractionModeChange('select')}
        title="V - Select nodes"
        type="button"
      >
        <MousePointer2 aria-hidden="true" size={20} strokeWidth={1.75} />
      </ControlButton>
      <ControlButton
        aria-label="Pan canvas"
        aria-pressed={interactionMode === 'pan'}
        className={interactionMode === 'pan' ? activeControlClassName : undefined}
        onClick={() => onInteractionModeChange('pan')}
        title="H - Pan canvas"
        type="button"
      >
        <Hand aria-hidden="true" size={20} strokeWidth={1.75} />
      </ControlButton>
      <ControlButton
        aria-label={isSnapEnabled ? 'Turn snapping off' : 'Turn snapping on'}
        aria-pressed={isSnapEnabled}
        className={isSnapEnabled ? activeControlClassName : undefined}
        onClick={onSnapToggle}
        title={`S - ${isSnapEnabled ? 'Turn grid snap off' : 'Turn grid snap on'}`}
        type="button"
      >
        <Grid2X2 aria-hidden="true" size={20} strokeWidth={1.75} />
      </ControlButton>
    </>
  );
}

function RcaCanvasContextMenu({
  canvasTheme,
  canAddFishbone,
  canAddFiveWhys,
  canAddNode,
  canCreateIncidentNode,
  canDeleteNode,
  canEditNode,
  canGenerateReport,
  canRearrange,
  canReactToNode,
  contextMenu,
  gridSize,
  hasContainmentOrProblemCanvasNode,
  hasIncidentDetailsCanvasNode,
  isGridVisible,
  isSnapEnabled,
  isWorking,
  methodology,
  missingFishboneBranches,
  onAddFishbone,
  onAddFishboneBranch,
  onAddFiveWhys,
  nodeMenuKind,
  onAddFiveWhysNodeRole,
  onAddNode,
  onAddSubCause,
  onAddStickyNote,
  onAddComment,
  onClearCanvas,
  onCreateIncident,
  onCopyText,
  onDeleteNode,
  onEditNode,
  onGenerateReport,
  onNodeDetails,
  onOpenReactions,
  onPasteText,
  onGridSizeChange,
  onGridToggle,
  onMethodologyChange,
  onRearrange,
  onRefresh,
  onShortcutListOpen,
  onSnapToggle,
  onThemeChange
}: {
  canvasTheme: RcaCanvasTheme;
  canAddFishbone: boolean;
  canAddFiveWhys: boolean;
  canAddNode: boolean;
  canCreateIncidentNode: boolean;
  canDeleteNode: boolean;
  canEditNode: boolean;
  canGenerateReport: boolean;
  canRearrange: boolean;
  canReactToNode: boolean;
  contextMenu: RcaCanvasContextMenuState | null;
  gridSize: number;
  hasContainmentOrProblemCanvasNode: boolean;
  hasIncidentDetailsCanvasNode: boolean;
  isGridVisible: boolean;
  isSnapEnabled: boolean;
  isWorking: boolean;
  methodology: RcaMethodology;
  missingFishboneBranches: RcaMissingFishboneBranchOption[];
  onAddFishbone: () => void;
  onAddFishboneBranch: (branchLabel: string) => void;
  onAddFiveWhys: () => void;
  nodeMenuKind: RcaNodeContextMenuKind | null;
  onAddFiveWhysNodeRole: (role: RcaFiveWhysNodeRole) => void;
  onAddNode: () => void;
  onAddSubCause: () => void;
  onAddStickyNote: () => void;
  onAddComment: () => void;
  onClearCanvas: () => void;
  onCreateIncident: () => void;
  onCopyText: () => void;
  onDeleteNode: () => void;
  onEditNode: () => void;
  onGenerateReport: () => void;
  onNodeDetails: () => void;
  onOpenReactions: () => void;
  onPasteText: () => void;
  onGridSizeChange: (size: number) => void;
  onGridToggle: () => void;
  onMethodologyChange: (methodology: RcaMethodology) => void;
  onRearrange: () => void;
  onRefresh: () => void;
  onShortcutListOpen: () => void;
  onSnapToggle: () => void;
  onThemeChange: (theme: RcaCanvasTheme) => void;
}) {
  const [isAddNodeSubmenuOpen, setIsAddNodeSubmenuOpen] = React.useState(false);
  const [isBranchSubmenuOpen, setIsBranchSubmenuOpen] = React.useState(false);
  const [isCapaSubmenuOpen, setIsCapaSubmenuOpen] = React.useState(false);
  const [isSettingsSubmenuOpen, setIsSettingsSubmenuOpen] = React.useState(false);
  const [isThemeSubmenuOpen, setIsThemeSubmenuOpen] = React.useState(false);

  React.useEffect(() => {
    setIsAddNodeSubmenuOpen(false);
    setIsBranchSubmenuOpen(false);
    setIsCapaSubmenuOpen(false);
    setIsSettingsSubmenuOpen(false);
    setIsThemeSubmenuOpen(false);
  }, [contextMenu?.targetNodeId, contextMenu?.x, contextMenu?.y]);

  if (!contextMenu) {
    return null;
  }

  const gridSizePercent = Math.round((gridSize / RCA_CANVAS_GRID_DEFAULT_SIZE) * 100);
  const submenuPlacementClassName = contextMenu.submenuPlacement === 'right'
    ? 'left-[calc(100%+6px)] origin-top-left'
    : 'right-[calc(100%+6px)] origin-top-right';
  const isNodeTargetMenu = Boolean(contextMenu.targetNodeId);
  const isEmptyCanvasPaneMenu = !contextMenu.targetNodeId && contextMenu.isCanvasPaneTarget;
  const isEditableNodeTarget = nodeMenuKind === 'cause' || nodeMenuKind === 'sticky' || nodeMenuKind === 'comment';
  const shouldShowCopyText = isEditableNodeTarget;
  const shouldShowPasteText = isEditableNodeTarget && Boolean(contextMenu.hasClipboardText);
  const canAddPostIncidentDetailsNode = canAddNode && hasIncidentDetailsCanvasNode;
  const canAddPostContainmentOrProblemNode = canAddPostIncidentDetailsNode && hasContainmentOrProblemCanvasNode;
  const hasMissingFishboneBranch = missingFishboneBranches.some((branch) => !branch.disabled);
  const canAddRoleFromFlowGate = (role: RcaFiveWhysNodeRole) => {
    if (role === 'INCIDENT_DETAILS') {
      return true;
    }

    if (!hasIncidentDetailsCanvasNode) {
      return false;
    }

    if (RCA_ROLES_REQUIRING_CONTAINMENT_OR_PROBLEM.has(role)) {
      return hasContainmentOrProblemCanvasNode;
    }

    return true;
  };

  return (
    <div
      className={`rca-context-menu absolute z-[90] rounded-xl border border-white/70 bg-white/95 p-1 text-slate-700 shadow-[0_20px_58px_rgba(15,23,42,0.2),0_4px_14px_rgba(14,165,233,0.12)] ring-1 ring-slate-900/5 backdrop-blur-xl ${
        isNodeTargetMenu ? 'w-[176px]' : 'w-[196px]'
      }`}
      onClick={(event) => event.stopPropagation()}
      onContextMenu={(event) => event.preventDefault()}
      onMouseDown={(event) => event.stopPropagation()}
      style={{ left: contextMenu.x, top: contextMenu.y }}
    >
      {nodeMenuKind === 'category' ? (
        <>
          <RcaContextMenuItem
            disabled={!canAddPostIncidentDetailsNode || isWorking}
            icon={Plus}
            label="Add Node"
            onClick={onAddNode}
          />
          <RcaContextMenuItem
            disabled={!canEditNode || isWorking}
            icon={Palette}
            label="Edit Node"
            onClick={onEditNode}
            shortcut="E"
          />
          <RcaContextMenuItem
            disabled={!canEditNode || isWorking}
            icon={PanelRightOpen}
            label="Node Details"
            onClick={onNodeDetails}
            shortcut="D"
          />
          <RcaContextMenuItem
            disabled={!canReactToNode || isWorking}
            icon={SmilePlus}
            label="Add Reaction"
            onClick={onOpenReactions}
          />
          <RcaContextMenuItem
            disabled={!canDeleteNode || isWorking}
            icon={Trash2}
            label="Delete Branch"
            onClick={onDeleteNode}
            tone="danger"
          />
        </>
      ) : nodeMenuKind === 'faultGate' ? (
        <>
          <div className="group/branch-node relative">
            <RcaContextMenuItem
              disabled={!hasMissingFishboneBranch || isWorking}
              icon={GitBranch}
              label="Add Branch"
              onClick={() => {
                setIsBranchSubmenuOpen((isOpen) => !isOpen);
                setIsAddNodeSubmenuOpen(false);
                setIsCapaSubmenuOpen(false);
                setIsSettingsSubmenuOpen(false);
                setIsThemeSubmenuOpen(false);
              }}
              rightSlot={<ChevronRight aria-hidden="true" size={11} strokeWidth={2} />}
            />
            <div className={`${isBranchSubmenuOpen ? 'pointer-events-auto translate-y-0 scale-100 opacity-100' : 'pointer-events-none translate-y-1 scale-95 opacity-0 group-hover/branch-node:pointer-events-auto group-hover/branch-node:translate-y-0 group-hover/branch-node:scale-100 group-hover/branch-node:opacity-100'} absolute top-0 z-[94] w-[218px] rounded-xl border border-white/70 bg-white/95 p-1 shadow-[0_18px_48px_rgba(15,23,42,0.17)] ring-1 ring-slate-900/5 backdrop-blur-xl transition duration-150 ease-out ${submenuPlacementClassName}`}>
              {missingFishboneBranches.map((branch) => (
                <RcaContextMenuItem
                  disabled={branch.disabled || isWorking}
                  icon={GitBranch}
                  key={branch.label}
                  label={branch.label}
                  onClick={() => onAddFishboneBranch(branch.label)}
                  rightSlot={branch.disabled ? <CheckCircle2 aria-hidden="true" size={11} strokeWidth={2} /> : null}
                />
              ))}
            </div>
          </div>
          <RcaContextMenuItem
            disabled={!canEditNode || isWorking}
            icon={Palette}
            label="Edit Node"
            onClick={onEditNode}
            shortcut="E"
          />
          <RcaContextMenuItem
            disabled={!canEditNode || isWorking}
            icon={PanelRightOpen}
            label="Node Details"
            onClick={onNodeDetails}
            shortcut="D"
          />
          <RcaContextMenuItem
            disabled={!canReactToNode || isWorking}
            icon={SmilePlus}
            label="Add Reaction"
            onClick={onOpenReactions}
          />
          <RcaContextMenuItem
            disabled={!canDeleteNode || isWorking}
            icon={Trash2}
            label="Delete Fishbone"
            onClick={onDeleteNode}
            tone="danger"
          />
        </>
      ) : nodeMenuKind === 'cause' ? (
        <>
          <RcaContextMenuItem
            disabled={!canAddPostIncidentDetailsNode || isWorking}
            icon={GitBranch}
            label="Add Sub Cause"
            onClick={onAddSubCause}
          />
          <RcaContextMenuItem
            disabled={!canEditNode || isWorking}
            icon={Palette}
            label="Edit Node"
            onClick={onEditNode}
            shortcut="E"
          />
          <RcaContextMenuItem
            disabled={!canEditNode || isWorking}
            icon={PanelRightOpen}
            label="Node Details"
            onClick={onNodeDetails}
            shortcut="D"
          />
          <RcaContextMenuItem
            disabled={!canReactToNode || isWorking}
            icon={SmilePlus}
            label="Add Reaction"
            onClick={onOpenReactions}
          />
          {canGenerateReport ? (
            <RcaContextMenuItem
              disabled={isWorking}
              icon={FileText}
              label="Generate RCA Report"
              onClick={onGenerateReport}
            />
          ) : null}
          {shouldShowCopyText ? (
            <RcaContextMenuItem
              disabled={isWorking}
              icon={ClipboardCopy}
              label={contextMenu.hasSelectedText ? 'Copy Text' : 'Copy Node Text'}
              onClick={onCopyText}
            />
          ) : null}
          {shouldShowPasteText ? (
            <RcaContextMenuItem
              disabled={isWorking}
              icon={ClipboardPaste}
              label="Paste Text"
              onClick={onPasteText}
            />
          ) : null}
          <RcaContextMenuItem
            disabled={!canDeleteNode || isWorking}
            icon={Trash2}
            label="Delete Node"
            onClick={onDeleteNode}
            tone="danger"
          />
        </>
      ) : nodeMenuKind === 'sticky' || nodeMenuKind === 'comment' ? (
        <>
          <RcaContextMenuItem
            disabled={!canEditNode || isWorking}
            icon={Palette}
            label="Edit Node"
            onClick={onEditNode}
            shortcut="E"
          />
          <RcaContextMenuItem
            disabled={!canEditNode || isWorking}
            icon={PanelRightOpen}
            label="Node Details"
            onClick={onNodeDetails}
            shortcut="D"
          />
          <RcaContextMenuItem
            disabled={!canReactToNode || isWorking}
            icon={SmilePlus}
            label="Add Reaction"
            onClick={onOpenReactions}
          />
          {shouldShowCopyText ? (
            <RcaContextMenuItem
              disabled={isWorking}
              icon={ClipboardCopy}
              label={contextMenu.hasSelectedText ? 'Copy Text' : nodeMenuKind === 'comment' ? 'Copy Comment Text' : 'Copy Note Text'}
              onClick={onCopyText}
            />
          ) : null}
          {shouldShowPasteText ? (
            <RcaContextMenuItem
              disabled={isWorking}
              icon={ClipboardPaste}
              label="Paste Text"
              onClick={onPasteText}
            />
          ) : null}
          <RcaContextMenuItem
            disabled={!canDeleteNode || isWorking}
            icon={Trash2}
            label={nodeMenuKind === 'comment' ? 'Delete Comment' : 'Delete Note'}
            onClick={onDeleteNode}
            tone="danger"
          />
        </>
      ) : (
        <>
          {isNodeTargetMenu ? (
            <>
              <RcaContextMenuItem
                disabled={!canReactToNode || isWorking}
                icon={SmilePlus}
                label="Add Reaction"
                onClick={onOpenReactions}
              />
              <div className="my-1 h-px bg-slate-200/80" />
            </>
          ) : null}
          <div className="group/add-node relative">
            <RcaContextMenuItem
              disabled={!canAddNode || isWorking}
              icon={Plus}
              label="Add Node"
              onClick={() => {
                setIsAddNodeSubmenuOpen((isOpen) => !isOpen);
                setIsCapaSubmenuOpen(false);
                setIsSettingsSubmenuOpen(false);
                setIsThemeSubmenuOpen(false);
              }}
              rightSlot={<ChevronRight aria-hidden="true" size={11} strokeWidth={2} />}
              shortcut="N"
            />
            <div className={`${isAddNodeSubmenuOpen ? 'pointer-events-auto translate-y-0 scale-100 opacity-100' : 'pointer-events-none translate-y-1 scale-95 opacity-0 group-hover/add-node:pointer-events-auto group-hover/add-node:translate-y-0 group-hover/add-node:scale-100 group-hover/add-node:opacity-100'} absolute top-0 z-[92] w-[218px] rounded-xl border border-white/70 bg-white/95 p-1 shadow-[0_18px_48px_rgba(15,23,42,0.17)] ring-1 ring-slate-900/5 backdrop-blur-xl transition duration-150 ease-out ${submenuPlacementClassName}`}>
              <RcaContextMenuItem
                disabled={!canAddPostContainmentOrProblemNode || isWorking}
                icon={GitBranch}
                label="Cause"
                onClick={onAddNode}
              />
              <div className="my-1 h-px bg-slate-200/80" />
              {RCA_ADD_NODE_ROLE_OPTIONS.map((option) => (
                <RcaContextMenuItem
                  disabled={!canAddNode || isWorking || !canAddRoleFromFlowGate(option.value)}
                  icon={option.icon}
                  key={option.value}
                  label={option.label}
                  onClick={() => onAddFiveWhysNodeRole(option.value)}
                />
              ))}
              <div className="my-1 h-px bg-slate-200/80" />
              <RcaContextMenuItem
                disabled={!canAddFishbone || isWorking}
                icon={GitBranch}
                label="Fishbone"
                onClick={onAddFishbone}
              />
              <RcaContextMenuItem
                disabled={!canAddFiveWhys || isWorking}
                icon={ListChecks}
                label="5 Whys"
                onClick={onAddFiveWhys}
              />
              <div className="group/capa-node relative">
              <RcaContextMenuItem
                disabled={!canAddPostContainmentOrProblemNode || isWorking}
                icon={PackageCheck}
                label="CAPA Stages"
                onClick={() => {
                  setIsCapaSubmenuOpen((isOpen) => !isOpen);
                  setIsSettingsSubmenuOpen(false);
                  setIsThemeSubmenuOpen(false);
                }}
                rightSlot={<ChevronRight aria-hidden="true" size={11} strokeWidth={2} />}
              />
                <div className={`${isCapaSubmenuOpen ? 'pointer-events-auto translate-y-0 scale-100 opacity-100' : 'pointer-events-none translate-y-1 scale-95 opacity-0 group-hover/capa-node:pointer-events-auto group-hover/capa-node:translate-y-0 group-hover/capa-node:scale-100 group-hover/capa-node:opacity-100'} absolute top-0 z-[94] w-[218px] rounded-xl border border-white/70 bg-white/95 p-1 shadow-[0_18px_48px_rgba(15,23,42,0.17)] ring-1 ring-slate-900/5 backdrop-blur-xl transition duration-150 ease-out ${submenuPlacementClassName}`}>
                  {RCA_CAPA_NODE_ROLE_OPTIONS.map((option) => (
                    <RcaContextMenuItem
                      disabled={!canAddPostContainmentOrProblemNode || isWorking}
                      icon={option.icon}
                      key={option.value}
                      label={option.label}
                      onClick={() => onAddFiveWhysNodeRole(option.value)}
                    />
                  ))}
                </div>
              </div>
            </div>
          </div>
          <RcaContextMenuItem
            disabled={!canAddPostIncidentDetailsNode || isWorking}
            icon={StickyNote}
            label="Sticky Note"
            onClick={onAddStickyNote}
          />
          <RcaContextMenuItem
            disabled={!canAddPostIncidentDetailsNode || isWorking}
            icon={MessageSquareText}
            label="Comment"
            onClick={onAddComment}
          />
          <RcaContextMenuItem
            disabled={!canCreateIncidentNode || isWorking}
            icon={FilePlus2}
            label="Incident"
            onClick={onCreateIncident}
          />
          <RcaContextMenuItem
            disabled={!canGenerateReport || isWorking}
            icon={FileText}
            label="Generate RCA Report"
            onClick={onGenerateReport}
          />
          {methodologyOptions.map((option) => (
            <RcaContextMenuItem
              active={option.value === methodology}
              disabled={isWorking}
              icon={option.icon}
              key={option.value}
              label={option.label}
              onClick={() => onMethodologyChange(option.value)}
              rightSlot={option.value === methodology ? <CheckCircle2 aria-hidden="true" size={11} strokeWidth={2} /> : null}
              shortcut={option.shortcut}
            />
          ))}
          <div className="my-1 h-px bg-slate-200/80" />
          <RcaContextMenuItem
            disabled={!canRearrange || isWorking}
            icon={AlignHorizontalSpaceBetween}
            label="Rearrange Canvas"
            onClick={onRearrange}
            shortcut="R"
          />
          {isEmptyCanvasPaneMenu ? (
            <RcaContextMenuItem
              disabled={isWorking}
              icon={RefreshCw}
              label="Refresh Canvas"
              onClick={onRefresh}
              shortcut="Shift+R"
            />
          ) : null}
          <div
            className="group/settings relative"
            onMouseEnter={() => {
              setIsSettingsSubmenuOpen(true);
              setIsAddNodeSubmenuOpen(false);
              setIsBranchSubmenuOpen(false);
              setIsCapaSubmenuOpen(false);
            }}
          >
            <RcaContextMenuItem
              icon={Settings2}
              label="Settings"
              onClick={() => {
                setIsSettingsSubmenuOpen((isOpen) => !isOpen);
                setIsAddNodeSubmenuOpen(false);
                setIsBranchSubmenuOpen(false);
                setIsCapaSubmenuOpen(false);
                setIsThemeSubmenuOpen(false);
              }}
              rightSlot={<ChevronRight aria-hidden="true" size={11} strokeWidth={2} />}
            />
            <div className={`${isSettingsSubmenuOpen ? 'pointer-events-auto translate-y-0 scale-100 opacity-100' : 'pointer-events-none translate-y-1 scale-95 opacity-0 group-hover/settings:pointer-events-auto group-hover/settings:translate-y-0 group-hover/settings:scale-100 group-hover/settings:opacity-100'} absolute top-0 z-[92] w-[216px] rounded-xl border border-white/70 bg-white/95 p-1 shadow-[0_18px_48px_rgba(15,23,42,0.17)] ring-1 ring-slate-900/5 backdrop-blur-xl transition duration-150 ease-out ${submenuPlacementClassName}`}>
              <RcaContextMenuItem
                active={isGridVisible}
                icon={Grid2X2}
                label={isGridVisible ? 'Turn Grid off' : 'Turn Grid on'}
                onClick={onGridToggle}
                shortcut="G"
              />
              <div
                className="rounded-lg px-2 py-1.5"
                onClick={(event) => event.stopPropagation()}
                onMouseDown={(event) => event.stopPropagation()}
              >
                <div className="mb-1 flex items-center justify-between gap-2 text-[10px] font-medium leading-none text-slate-600">
                  <span className={`inline-flex items-center gap-1.5 ${isGridVisible ? 'text-emerald-700' : ''}`}>
                    <Grid2X2 aria-hidden="true" size={11} strokeWidth={1.9} />
                    Grid size
                  </span>
                  <span className={`rounded-full px-1.5 py-0.5 text-[9px] font-semibold ${
                    isGridVisible ? 'bg-emerald-50 text-emerald-700 ring-1 ring-emerald-100' : 'bg-slate-100 text-slate-500'
                  }`}>
                    {gridSizePercent}%
                  </span>
                </div>
                <input
                  aria-label="Grid size"
                  aria-valuetext={`${gridSizePercent}%`}
                  className="block h-4 w-full accent-emerald-600"
                  max={RCA_CANVAS_GRID_MAX_SIZE}
                  min={RCA_CANVAS_GRID_MIN_SIZE}
                  onChange={(event) => onGridSizeChange(Number(event.target.value))}
                  step={RCA_CANVAS_GRID_STEP}
                  type="range"
                  value={gridSize}
                />
              </div>
              <div
                className="group/theme relative"
                onMouseEnter={() => setIsThemeSubmenuOpen(true)}
              >
                <RcaContextMenuItem
                  icon={Palette}
                  label="Canvas theme"
                  onClick={() => setIsThemeSubmenuOpen((isOpen) => !isOpen)}
                  rightSlot={<ChevronRight aria-hidden="true" size={11} strokeWidth={2} />}
                />
                <div className={`${isThemeSubmenuOpen ? 'pointer-events-auto translate-y-0 scale-100 opacity-100' : 'pointer-events-none translate-y-1 scale-95 opacity-0 group-hover/theme:pointer-events-auto group-hover/theme:translate-y-0 group-hover/theme:scale-100 group-hover/theme:opacity-100'} absolute top-0 z-[94] w-[172px] rounded-xl border border-white/70 bg-white/95 p-1 shadow-[0_18px_48px_rgba(15,23,42,0.17)] ring-1 ring-slate-900/5 backdrop-blur-xl transition duration-150 ease-out ${submenuPlacementClassName}`}>
                  {RCA_CANVAS_THEME_OPTIONS.map((option) => (
                    <RcaContextMenuItem
                      active={option.value === canvasTheme}
                      icon={option.icon}
                      key={option.value}
                      label={option.label}
                      onClick={() => onThemeChange(option.value)}
                      rightSlot={option.value === canvasTheme ? <CheckCircle2 aria-hidden="true" size={11} strokeWidth={2} /> : null}
                    />
                  ))}
                </div>
              </div>
              <RcaContextMenuItem
                active={isSnapEnabled}
                icon={Grid2X2}
                label={isSnapEnabled ? 'Grid snap On' : 'Grid snap Off'}
                onClick={onSnapToggle}
                shortcut="S"
              />
              <div className="my-1 h-px bg-slate-200/80" />
              <RcaContextMenuItem
                disabled={isWorking}
                icon={Trash2}
                label="Clear Canvas"
                onClick={onClearCanvas}
                tone="danger"
              />
              <div className="my-1 h-px bg-slate-200/80" />
              <RcaContextMenuItem
                icon={ClipboardList}
                label="Shortcut list"
                onClick={onShortcutListOpen}
                shortcut="?"
              />
            </div>
          </div>
        </>
      )}
    </div>
  );
}

